def main():
    downloads=json.loads((BASE/"download_manifest.json").read_text(encoding="utf-8"))
    codes=json.loads((BASE/"code_manifest.json").read_text(encoding="utf-8"))
    for source in SOURCES:
        ids=[source["id"]]+source.get("alternate_download_ids",[])
        source["access"]={"full_text_available":True,"relevant_sections_inspected":True,"downloads":[x for x in downloads if x["id"] in ids],"code_inspection":[x for x in codes if x["repository"] in source["repositories"]],"experiments_reproduced":False}
    for supplement_name in ("supplementary_sources.json", "revision_sources.json"):
        supplement_path = BASE / supplement_name
        if supplement_path.exists():
            supplement = json.loads(supplement_path.read_text(encoding="utf-8"))
            for source in supplement["sources"]:
                # Preserve explicit metadata-only access flags for inaccessible papers.
                source["access"]["downloads"] = [x for x in downloads if x["id"] == source["id"]]
                SOURCES.append(source)
    ledger={"audit_date":"2026-09-26","literature_cutoff":"2026-09-26","page_number_convention":"One-based page index of archived PDF, not necessarily printed proceedings pagination.","search_scope":"Targeted closest-work audit; not an exhaustive systematic review or proof of priority.","retrieval_routes":["agent-reach Exa search/fetch connector","web tool for primary metadata","public publisher/arXiv/author PDF downloads","agent-reach GitHub CLI read-only API"],"exact_search_queries_this_pass":["\"knowledge tracing\" \"repeated attempts\" \"learning gain\" programming Code-DKT reliability","\"Your Model Is Predictive\" \"Useful\" González-Brenes Huang 2015","site.educationaldatamining.org/EDM2015 \"Your Model\""],"sources":SOURCES}
    (BASE/"sources.json").write_text(json.dumps(ledger,ensure_ascii=False,indent=2),encoding="utf-8")
    print(f"Wrote {len(SOURCES)} verified source records.")

if __name__=="__main__": main()
